import type {PlanPictorialSpec,PlanPictorialOptions} from '../../../src/plan.js';
export type ExampleId='grouped'|'capacity'|'sum'|'percent'|'incomplete'|'heart'|'custom-ring'|'zero';
export const exampleIds:readonly ExampleId[]=['grouped','capacity','sum','percent','incomplete','heart','custom-ring','zero'];
export function pictorialExample(id:ExampleId,locale:'es'|'en'):{spec:PlanPictorialSpec;options:PlanPictorialOptions;note:string}{
  const es=locale==='es',titles={grouped:es?'Capacidad por equipo':'Capacity by team',capacity:es?'Objetivo común':'A shared target',sum:es?'Un total compartido':'One shared total',percent:es?'Proporciones conocidas':'Known proportions',incomplete:es?'Información incompleta':'Incomplete information',heart:es?'Un relleno con forma':'A shaped fill','custom-ring':es?'Un contorno con un hueco':'An outline with a hole',zero:es?'Cero conserva su significado':'Zero keeps its meaning'};
  const values= id==='zero'?[[0,0]]:id==='incomplete'?[[35,null],[null,25]]:[[35,50],[25,30]];
  const ring={id:'ring',aspectRatio:1,vertices:[{x:0,y:0},{x:1,y:0},{x:1,y:1},{x:0,y:1},{x:.3,y:.3},{x:.7,y:.3},{x:.7,y:.7},{x:.3,y:.7}],triangles:[[0,1,5],[0,5,4],[1,2,6],[1,6,5],[2,3,7],[2,7,6],[3,0,4],[3,4,7]] as const};
  const shape=id==='custom-ring'?{kind:'mesh' as const,mesh:ring}:{kind:'preset' as const,name:id==='heart'?'heart' as const:id==='grouped'?'person' as const:'bottle' as const};
  const notes={grouped:es?'Cada serie conserva una silueta independiente con la misma escala.':'Each series has its own silhouette with a common scale.',capacity:es?'La altura completa representa el objetivo de 100 unidades.':'Full height represents the target of 100 units.',sum:es?'Las series dividen una única silueta en bandas acumuladas.':'Series divide one silhouette into cumulative bands.',percent:es?'Cada categoría completa suma el 100 % de sus valores conocidos.':'Each complete category totals 100% of its known values.',incomplete:es?'Los valores ausentes no se convierten en cero. Los porcentajes describen sólo lo conocido.':'Unknown values do not become zero. Percentages describe only the known subset.',heart:es?'La proporción se mide por altura, no por área.':'The proportion measures height, not area.','custom-ring':es?'El hueco queda vacío y no intercepta pulsaciones.':'The hole remains empty and does not intercept touches.',zero:es?'Los ceros no generan un relleno ficticio; siguen disponibles por teclado y en los datos.':'Zeros create no artificial fill; they remain available through keyboard navigation and source data.'};
  return{spec:{family:'pictorial',title:titles[id],description:es?'Toca un relleno para consultar su valor.':'Touch a fill to inspect its value.',axes:{x:{kind:'category',values:[{id:'a',label:es?'Equipo A':'Team A'},{id:'b',label:es?'Equipo B':'Team B'}]},y:{kind:'linear',...(id==='capacity'?{domain:[0,100] as const}:{}),unit:es?'unidades':'units'}},series:values.map((ys,i)=>({id:'s'+i,name:(es?'Grupo ':'Group ')+(i+1),data:ys.map((y,j)=>({id:'p'+j,x:j?'b':'a',y}))})),pictorial:{shape}},options:{width:360,height:320,...(id==='sum'?{stacking:'sum' as const}:id==='percent'||id==='incomplete'?{stacking:'percent' as const}:{})},note:notes[id]};
}
